# The rules are embedded in the todos_content string. I'll use an LLM to extract them.
rules_schema = {
    "type": "object",
    "properties": {
        "rules": {
            "type": "array",
            "items": {"type": "string"}
        }
    },
    "required": ["rules"]
}

rules_extraction_prompt = {
    "task": "Extract the rules for fruit analysis from the provided text. Return them as a list of strings.",
    "context": todos_content
}

extracted_rules = await llm_query(rules_extraction_prompt, schema=rules_schema)
print(f"Extracted rules: {extracted_rules['rules']}")

